(() => {
const host=document.querySelector('[data-site-header]'); if(!host) return;
host.outerHTML="<header class=\"site-header\"><div class=\"wrap nav\">\n<a class=\"brand\" href=\"#\" aria-label=\"Millî Gençlik Derneği ana sayfa\"><span class=\"brand-logo\"><img src=\"assets/logo-horizontal-white.png\" width=\"1440\" height=\"1080\" alt=\"Millî Gençlik Derneği\"></span></a>\n<button class=\"menu-toggle\" aria-label=\"Menüyü aç\" aria-expanded=\"false\">☰</button>\n<nav aria-label=\"Ana menü\">\n<button class=\"nav-link\" data-page=\"kurumsal\">Kurumsal <span class=\"nav-chevron\" aria-hidden=\"true\"><svg viewBox=\"0 0 16 16\"><path d=\"m3.5 5.75 4.5 4.5 4.5-4.5\"></path></svg></span></button>\n<div class=\"dropdown\"><button class=\"nav-link dropdown-trigger\" aria-expanded=\"false\" aria-controls=\"management-submenu\">Yönetim <span class=\"nav-chevron\" aria-hidden=\"true\"><svg viewBox=\"0 0 16 16\"><path d=\"m3.5 5.75 4.5 4.5 4.5-4.5\"></path></svg></span></button><div class=\"submenu\" id=\"management-submenu\" inert><a href=\"#yonetim\" data-tab=\"president\">Genel Başkan</a><a href=\"divan.html\">Başkanlık Divanı</a><a href=\"#subeler\">Şube Başkanları</a></div></div>\n<button class=\"nav-link\" data-page=\"erbakan\">Öncü Şahsiyetler <span class=\"nav-chevron\" aria-hidden=\"true\"><svg viewBox=\"0 0 16 16\"><path d=\"m3.5 5.75 4.5 4.5 4.5-4.5\"></path></svg></span></button>\n<div class=\"dropdown media-dropdown\"><a class=\"nav-link dropdown-trigger\" href=\"media.html\" aria-expanded=\"false\" aria-controls=\"media-submenu\">Medya ve Yayınlar <span class=\"nav-chevron\" aria-hidden=\"true\"><svg viewBox=\"0 0 16 16\"><path d=\"m3.5 5.75 4.5 4.5 4.5-4.5\"></svg></span></a><div class=\"submenu\" id=\"media-submenu\" inert><a href=\"media.html?category=Konseptler\" data-media-filter=\"Konseptler\">Konseptler</a><a href=\"media.html?category=Broşür%20ve%20Pankartlar\" data-media-filter=\"Broşür ve Pankartlar\">Broşür ve Pankartlar</a><a href=\"media.html?category=Yayınlarımız\" data-media-filter=\"Yayınlarımız\">Yayınlarımız</a><a href=\"media.html?category=Kurumsal%20Kimlik\" data-media-filter=\"Kurumsal Kimlik\">Kurumsal Kimlik</a></div></div>\n<a class=\"nav-link\" href=\"#iletisim\">İletişim</a>\n</nav>\n<div class=\"header-actions\">\n<button id=\"search-toggle\" class=\"search-toggle\" aria-label=\"Sitede ara\" title=\"Sitede ara\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"10.8\" cy=\"10.8\" r=\"6.7\"></circle><path d=\"m16 16 5 5\"></path></svg></button>\n<button class=\"member-cta\" data-volunteer><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 12a4.1 4.1 0 1 0 0-8.2 4.1 4.1 0 0 0 0 8.2Z\"></path><path d=\"M4.5 20c.5-3.4 3.2-5.4 7.5-5.4s7 2 7.5 5.4\"></path></svg><span>Üyelik / Başvuru</span></button>\n</div></div></header>";
const nav=document.querySelector('.site-header nav'),toggle=document.querySelector('.menu-toggle');
if(toggle&&nav) toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))});
function closeAll(){document.querySelectorAll('.site-header .dropdown').forEach(d=>{d.classList.remove('is-open');d.querySelector('.submenu')?.classList.remove('open');d.querySelector('.submenu')?.setAttribute('inert','')})}
document.querySelectorAll('.site-header .dropdown').forEach(d=>{const trigger=d.querySelector('.dropdown-trigger'),sub=d.querySelector('.submenu');d.addEventListener('mouseenter',()=>{d.classList.add('is-open');sub?.removeAttribute('inert')});d.addEventListener('mouseleave',()=>{if(!sub?.classList.contains('open')){d.classList.remove('is-open');sub?.setAttribute('inert','')}});trigger?.addEventListener('click',e=>{if(trigger.tagName==='A')e.preventDefault();const open=!sub?.classList.contains('open');closeAll();if(open){d.classList.add('is-open');sub?.classList.add('open');sub?.removeAttribute('inert')}})});document.addEventListener('click',e=>{if(!e.target.closest('.site-header .dropdown'))closeAll()});
})();